INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES ("vo_travel_talk", 0, "", "vo_travel_talk_20018_01", 0, "", 21, 20182, "", 1201820007, "");
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (118011, 1, 0, "陛下直々のご命令とあれば、\nこのクレジッタ・キャッシュ！\nご満足いただける大秘宝を、\nなんとしても手に入れてみせますわ！", 10, 0, 11, 20182, 1, 1201820008, 0);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (0, "", "", "", "", "", 91, 20182, "", 1201820009, "");
