INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (106111, 1, 0, "よーし！　ネネカと一緒に冒険だ！\nせっかくだし、何か悪いことするか？\n七冠とやれば派手になりそうだしさ！", 10, 0, 11, 20192, 1, 1201920005, 0);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (0, "", "", "", "", "", 91, 20192, "", 1201920006, "");
