INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (102711, 1, 0, "私の行く手を阻むものは容赦なく\n壊しつくしますわ、クスクス。すべては\nあのおかたと私の未来のため……", 10, 0, 11, 20242, 1, 1202420005, 0);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (0, "", "", "", "", "", 91, 20242, "", 1202420006, "");
